-- M363-04.verweilzeit_gasdicht
update public.fields set verification_status='verified_against_standard', verification_quote='Weiterhin schreibt die TA Luft (2021) vor, dass ein- oder mehrstufige Biogasanlagen eine Verweilzeit im gasdichten System (inkl. Gärrestlagern) von insgesamt mindestens 150 Tage einzuhalten haben. Für mehrstufige Biogasanlagen mit einem Gülleanteil am Substratmix beträgt die Mindestverweilzeit mindestens 50 Tage zuzüglich je zwei Tage pro Masseprozentpunkt anderer Substrate als Gülle, maximal jedoch 150 Tage. — printed p.28', verification_note='md-verified 2026-09-05 (§5.5 (TA Luft 2021), printed p.28) [VC]', verified_at=now() where id='03beb4d1-0162-434e-9200-19909404d45c' and verification_status not in ('verified_against_standard','corrected');
