-- ===== M363-06 =====
-- M363-06.bevorratungszeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderlichen Gasspeicher waren mit einer Bevorratung von 2 h bis 6 h vergleichsweise klein und dienten vor allem dem Ausgleich von Schwankungen in der Gasproduktion. | Bevorratungszeiträume von 10 h bis 15 h (bezogen auf die Gasproduktion) stellen keine Seltenheit dar. In Einzelfällen wurden schon Gasspeicher mit einer Bevorratung von 60 h errichtet, um Wochenenden komplett ohne Stromeinspeisung überbrücken zu können. — printed p.35', verification_note='md-verified 2026-09-05 (§6.4, printed p.35) [VC]', verified_at=now() where id='4c8bee8e-7bc9-489e-87a6-bf19cfd35103' and verification_status not in ('verified_against_standard','corrected');
-- M363-06.speichervolumen_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Nachfolgend werden in Tabelle 12 Empfehlungen für die Auslegung des Biogasspeichervolumens in Abhängigkeit von der Anlagenart und Energieverwertung/-erzeugung aufgeführt. Sie können als Richtwert dienen, insbesondere dann, wenn keine ausreichenden anlagenspezifischen Kenntnisse zu Ganglinien von Gasanfall und -verbrauch vorliegen. | Tabelle 12: Orientierungswerte für die Auslegung des Biogasspeichervolumens | BHKW-Grundlast & $10 \%-30 \%$ & entsprechend dem Biogasanfall von ca. 2, 5 bis 7 Stunden — printed p.37', verification_note='md-verified 2026-09-05 (§6.6 Tab. 12, printed p.37) [VC]', verified_at=now() where id='7705caa3-4125-4473-b442-2a6efb00bbff' and verification_status not in ('verified_against_standard','corrected');
-- M363-06.ueberbauung_faktor
update public.fields set verification_status='verified_against_standard', verification_quote='Dazu ist laut EEG eine 2 - bis 5 -fache Überbauung erforderlich, d. h. bei gleicher Biogasproduktion übersteigt die Leistung des BHKW diese um den Faktor 2 bis 5. (Beispiel: eine 500 kW Biogaserzeugung wird mit einem BHKW mit einer Gesamtleistung von $2,0 \mathrm{MW}$ ausgestattet → entspricht 4-facher Überbauung). — printed p.35', verification_note='md-verified 2026-09-05 (§6.4, printed p.35) [VC]', verified_at=now() where id='761bd6bb-1256-4303-a9b7-c1e2a4eba7b9' and verification_status not in ('verified_against_standard','corrected');
-- M363-06.biogasausbeute_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 8: Praxisübliche Wirtschaftsdüngeranfallmengen je Tierkategorie sowie Biogasausbeuten beim Einsatz von Wirtschaftsdünger ${ }^{1)}$ in landwirtschaftlichen Biogasanlagen (Quelle: nach KTBL 2015 und KTBL 2014) | Gas-ertragsrichtwert & Biogas-ausbeute ${ }^{21}$ & Methan-Konzentration & Methananfall pro Tierplatz und Jahr | 2. Aufgrund der hohen Heterogenität von Wirtschaftsdüngern sind die hier genannten Zahlen lediglich als Anhaltswerte zu verstehen. Für eine belastbare Planungsgrundlage empfiehlt sich die Durchführung eines Gasertragstests zur Ermittlung der individuellen Gasausbeute des eingesetzten Materials (KTBL 2015). — printed p.25', verification_note='md-verified 2026-09-05 (§5.4 Tab. 8, printed p.25) [VC]', verified_at=now() where id='7d7e6de4-d9bc-4cd2-bdfe-0941536d0a7b' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-07 =====
-- M363-07.verdichtertyp
update public.fields set verification_status='verified_against_standard', verification_quote='Die Druckerhöhung hängt von den eingesetzten Verbrauchern und deren Vorgaben ab. Bei der BHKWTechnik sind Seitenkanalverdichter die verbreitetste Verdichterform. Alternativ kommen Radialventilatoren zum Einsatz. Bei höheren Drücken können auch Kolbenkompressoren oder Schraubenverdichter eingesetzt werden. — printed p.40', verification_note='md-verified 2026-09-05 (§6.8, printed p.40) [VC]', verified_at=now() where id='9857508a-d419-4366-846e-7c51cbf40a8e' and verification_status not in ('verified_against_standard','corrected');
-- M363-07.speicher_ummantelung
update public.fields set verification_status='verified_against_standard', verification_quote='Biogasspeicher können nach der Art ihrer Ummantelung wie folgt unterschieden werden (Bild 3): | Der Biogasspeicher mit Stahlummantelung besteht im Wesentlichen aus einem selbsttragenden Stahlmantel mit ebenem Boden und festem Dach. | Der Biogasspeicher mit Membranummantelung besteht aus einer Innenmembran, in der das Biogas gespeichert wird. Eine Außenmembran dient als Schutzhülle. | Es sind weitere Bauformen bekannt, deren Einsatzzahl bisher von untergeordneter Bedeutung ist und die deshalb im Weiteren nicht behandelt werden. — printed p.38', verification_note='md-verified 2026-09-05 (§6.7, printed p.38) [VC]', verified_at=now() where id='27faa151-9eea-492c-a68e-12ce326887a9' and verification_status not in ('verified_against_standard','corrected');
-- M363-07.speicherbetriebsdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Nach Art der Funktion bzw. der Erzeugung des Drucks werden folgende Behälter unterschieden: | In der Regel werden gewichtsbelastete Biogasspeicher in einem Druckbereich von 20 hPa bis 100 hPa betrieben. Es sind auch Ausführungen bis 200 hPa bekannt. | In der Regel werden stützluftbeaufschlagte Biogasspeicher in einem Druckbereich von 5 hPa bis 50 hPa betrieben. Es sind aber auch Ausführungen bis 100 hPa bekannt. | Das Eigengewicht der Membran erzeugt einen geringen Überdruck $(<1 \mathrm{hPa})$. | Formal stellt der Geltungsbereich der Druckgeräterichtlinie (Richtlinie 2014/68/EU) eine Grenze von 500 hPa dar, die mit Biogasspeichern mit gewichtsbelasteter Membran nicht überschritten werden sollte. — printed p.39', verification_note='md-verified 2026-09-05 (§6.7, printed p.39) [VC]', verified_at=now() where id='d30f04cb-616d-4e02-bae0-18cfb322e638' and verification_status not in ('verified_against_standard','corrected');
-- M363-07.speichertyp
update public.fields set verification_status='verified_against_standard', verification_quote='Gebräuchlich sind große Hochdruckspeicher bis zu einem Druck von 1 MPa . | Nach Art der Funktion bzw. der Erzeugung des Drucks werden folgende Behälter unterschieden: | In der Regel werden gewichtsbelastete Biogasspeicher in einem Druckbereich von 20 hPa bis 100 hPa betrieben. Es sind auch Ausführungen bis 200 hPa bekannt. | In der Regel werden stützluftbeaufschlagte Biogasspeicher in einem Druckbereich von 5 hPa bis 50 hPa betrieben. Es sind aber auch Ausführungen bis 100 hPa bekannt. | Das Eigengewicht der Membran erzeugt einen geringen Überdruck $(<1 \mathrm{hPa})$. — printed p.38', verification_note='md-verified 2026-09-05 (§6.7, printed p.38) [VC]', verified_at=now() where id='1381b03b-c64e-43dd-b519-ffe98853021b' and verification_status not in ('verified_against_standard','corrected');
-- M363-07.biogasausbeute_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 9: Richtwerte für die Gasausbeute nachwachsender Rohstoffe (Quelle: nach KTBL 2015) | Maissilage & & 35 & 95 & 650 & 52 & 340 | Grassilage & & 35 & 90 & 600 & 53 & 320 | Bei den Richtwerten für Gasausbeuten handelt es sich um statistisch abgesicherte Angaben aus Laboruntersuchungen, die zusätzlich mit einer Expertengruppe abgestimmt sind (KTBL 2013). — printed p.27', verification_note='md-verified 2026-09-05 (§5.5 Tab. 9, printed p.27) [VC]', verified_at=now() where id='dde3fb78-7ca3-48fd-8f40-52ba08f841d6' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-08 =====
-- M363-08.eta_th
update public.fields set verification_status='verified_against_standard', verification_quote='Der Wirkungsgrad der Heizkesselanlagen liegt in der Regel über $95 \%$. | Bei Nennlast können überschlägig, je nach Motorleistung ca. $33 \%$ bis zu $44 \%$ der eingesetzten Primärenergie in elektrische Energie und ca. $55 \%$ bis $48 \%$ in nutzbare thermische Energie umgesetzt werden. — printed p.43', verification_note='md-verified 2026-09-05 (§7.2; §7.3.2, printed p.43) [VC]', verified_at=now() where id='3243884a-3c21-49af-b609-2cca941edb2c' and verification_status not in ('verified_against_standard','corrected');
-- M363-08.eta_el
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Nennlast können überschlägig, je nach Motorleistung ca. $33 \%$ bis zu $44 \%$ der eingesetzten Primärenergie in elektrische Energie und ca. $55 \%$ bis $48 \%$ in nutzbare thermische Energie umgesetzt werden. | Der elektrische Wirkungsgrad von Gasturbinen liegt mit rund $25 \%$ bis $30 \%$ deutlich unter dem von Gasmotoren. | Mittels Wärmerückgewinnung durch einen integrierten Rekuperator werden elektrische Wirkungsgrade der reinen Mikrogasturbine von etwa $25 \%$ bis $31 \%$ erreicht. — printed p.44', verification_note='md-verified 2026-09-05 (§7.3.2; §7.3.3, printed p.44) [VC]', verified_at=now() where id='88b533f3-ff7e-4b85-ac98-260f6cbf7ad0' and verification_status not in ('verified_against_standard','corrected');
-- M363-08.verwertungsweg
update public.fields set verification_status='verified_against_standard', verification_quote='In Bild 4 sind Verwertungsmöglichkeiten, unterteilt in Wärmeerzeugung, Kraft-Wärme-Kopplung, Gasaufbereitung und sonstige Nutzung, aufgezeigt. | Folgende Verwertungsmöglichkeiten sind technisch ausgereift und in der Praxis bewährt: | I stationäre Gasmotoren, in der Regel als BHKW (Blockheizkraftwerk), | I Gasturbinen (konventionelle und Mikrogasturbinen) | I Kraftstoff zum Betrieb von Kraftfahrzeugen, | I Einspeisung in das Gasnetz, | I Abgabe des Biogases an Dritte zur Verwertung. — printed p.42', verification_note='md-verified 2026-09-05 (§7.1 Bild 4, printed p.42) [VC]', verified_at=now() where id='22a8ab84-7d16-423d-ab5d-7757353fab52' and verification_status not in ('verified_against_standard','corrected');
-- M363-08.biogasausbeute_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Die praktizierten Verweilzeiten bewegen sich zwischen 15 und 30 Tagen. Das entstehende Biogasgemisch hat einen Methangehalt von $55 \%$ bis $65 \%$. Die spezifische Biogasausbeute liegt bei etwa $0,3 \mathrm{~m}^{3}$ bis $0,6 \mathrm{~m}^{3} / \mathrm{kg}$ oTM. | Tabelle 10: Richtwerte für die Gasausbeute von Nebenprodukten und Reststoffen | Bioabfall ${ }^{11}$ & & 40 & 70 & 615 & 60 & 370 — printed p.29', verification_note='md-verified 2026-09-05 (§5.6 Tab. 10, printed p.29) [VC]', verified_at=now() where id='7992a460-95ea-415b-9a84-f48c35202454' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-09 =====
-- M363-09.privilegierung_baugb
update public.fields set verification_status='verified_against_standard', verification_quote='Biogasanlagen beziehungsweise „Anlagen, die der energetischen Nutzung von Biomasse dienen“ können unter bestimmten Voraussetzungen (siehe § 35 Absatz 1 Nr. 6 BauGB) privilegiert im Außenbereich errichtet werden. Biogasanlagen sind im Außenbereich im räumlichen Zusammenhang mit einem landwirtschaftlichen Betrieb zulässig, wenn öffentliche Belange nicht entgegenstehen, die | ausreichende Erschließung gesichert ist und wenn die Kapazität einer Anlage zur Erzeugung von Biogas 2,3 Mio. Normkubikmeter Biogas pro Jahr überschreitet. — printed p.55', verification_note='md-verified 2026-09-05 (§8.2 (BauGB § 35 Abs. 1 Nr. 6), printed p.55) [VC]', verified_at=now() where id='2f0917be-23e8-47e3-b1bb-dbfc1046963b' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.durchsatz_t_d
update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen zur biologischen Behandlung, soweit nicht durch Nummer 8.5 oder 8.7 erfasst, von | gefährlichen Abfällen & Durchsatzkapazität von $10 \mathrm{t} / \mathrm{d}$ oder mehr je Tag | nicht gefährlichen Abfällen, soweit nicht durch Nummer 8.6.3 erfasst & Durchsatzkapazität von $50 \mathrm{t} / \mathrm{d}$ oder mehr je Tag | nicht gefährlichen Abfällen, soweit nicht durch Nummer 8.6.3 erfasst & Durchsatzkapazität an Einsatzstoffen von $10 \mathrm{t} / \mathrm{d}$ bis weniger als $50 \mathrm{Mg} / \mathrm{d}$ — printed p.52', verification_note='md-verified 2026-09-05 (§8.1 Tab. 13 Nr. 8.6, printed p.52) [VC]', verified_at=now() where id='71e7daaa-f95b-45ef-9bc7-2cf62d1aa9cf' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.biogasmenge_total
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund der Brennbarkeit ist Biogas der Gefahrenkategorie „Entzündbare Gase“ (Kategorie Nr. 1.2.2 des Anhangs 1 der Störfall-Verordnung) zuzuordnen. Daraus ergibt sich, dass Biogasanlagen ab einer Menge von 10.000 kg Biogas den Grundpflichten und ab 50.000 kg den erweiterten Pflichten der Stör-fall-Verordnung unterliegen. Dabei sind die Mengen zu berücksichtigen, die in allen Anlagenteilen vorhanden sind oder vorhanden sein können. — printed p.54', verification_note='md-verified 2026-09-05 (§8.1 (12. BImSchV), printed p.54) [VC]', verified_at=now() where id='78db71df-85f0-44a4-bd46-2ca551864e72' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.co_substrat
update public.fields set verification_status='verified_against_standard', verification_quote='Der Begriff „Co-Vergärung“ bezeichnet die Mitbehandlung begrenzter Mengen eines Materials (Co- Substrat) in einer Vergärungsanlage, das von den (zunächst) vorgesehenen Hauptsubstraten abweicht. Häufig erfordert eine Co-Vergärung neben technischen Anpassungen der Anlage auch genehmigungsrechtliche Änderungen (Merkblatt DWA-M 380:2020). — printed p.11', verification_note='md-verified 2026-09-05 (§3.1; §5.8, printed p.11) [VC]', verified_at=now() where id='28a41a68-8949-4c3d-917b-9e4d58d09a76' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.feuerungswaermeleistung
update public.fields set verification_status='verified_against_standard', verification_quote='Abaasförmiaen Brennstoffen (... Klärgas ${ }^{(*)}$, Biogas) & Feuerungswärmeleistung von 10 MW bis weniger als 50 MW | Abaasförmiaen Brennstoffen (... Klärgas ${ }^{(*)}$, Biogas) bei Verbrennungsmotoranlagen oder Gasturbinenanlagen & Feuerungswärmeleistung von 1 MW bis weniger als 10 MW | Verbrennungsmotoranlagen oder Gasturbinenanlagen zum Antrieb von Arbeitsmaschinen für den Einsatz von ... Klärgas ${ }^{(*)}$, Biogas... & Feuerungswärmeleistung von 1 MW bis weniger als 50 MW — printed p.51', verification_note='md-verified 2026-09-05 (§8.1 Tab. 13, printed p.51) [VC]', verified_at=now() where id='a156cb95-90ca-432a-b1e9-97723356ee07' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.rohgas_kapazitaet
