-- M363-09.verfahrenstyp_bimschg
update public.fields set verification_status='verified_against_standard', verification_quote='Für immissionsschutzrechtlich genehmigungsbedürftige Anlagen ist je nach Leistungsgrenze das vereinfachte Verfahren nach § 19 BlmSchG oder ein förmliches Verfahren gemäß § 10 BlmSchG durchzuführen. | Das nicht förmliche (vereinfachte) Verfahren ist für die im Anhang 1 der 4. BlmSchV aufgeführten Anlagen, die in Spalte c mit einem „V“ gekennzeichnet sind, anzuwenden. | Immissionsschutzrechtlich nicht genehmigungsbedürftig sind alle Anlagen, die nicht im Anhang 1 der 4. BImSchV aufgeführt sind oder die die Leistungsgrenzen des Anhangs 1 der 4. BImSchV unterschreiten. — printed p.50', verification_note='md-verified 2026-09-05 (§8.1 (§§ 10, 19 BImSchG), printed p.50) [VC]', verified_at=now() where id='90a00c2f-9539-4616-8a48-3923d438d4ad' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.anlagen_nr_4bimschv
update public.fields set verification_status='verified_against_standard', verification_quote='Die im Kontext der Erzeugung, Verwertung/Nutzung und Lagerung von Biogasen relevanten Anlagen sind in Tabelle 13 zusammengestellt. | Tabelle 13: Bundesimmissionschutzrechtlich genehmigungsbedürftige Anlagen im Kontext der Erzeugung, Verwertung/Nutzung und Lagerung von Biogasen | Nr. (Anhang 1, 4. BlmSchV) & Anlagenart lgekürzter, z. T. sprachlich modifizierter Auszug aus Anhang 1, 4. BlmSchV) & Leistungsgrenzen / Anlagengrößen (gem. Anhang 1, 4. BlmSchV) & Zugehörige Nummer in der TA Luft 2021 — printed p.51', verification_note='md-verified 2026-09-05 (§8.1 Tab. 13, printed p.51) [VC]', verified_at=now() where id='3f3d5861-29cd-4c0f-b8c7-203151c81c4b' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.biogasausbeute_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Bei der Co-Vergärung sind die spezifischen Biogasausbeuten der jeweiligen Substratkomponenten zu erwarten. Die Biogasproduktionsraten pro Volumeneinheit des Fermenters können bei günstigen Stoffgemischen und optimierten Prozessbedingungen gegenüber der sonstigen Monovergärung (zum Beispiel Klärschlammfaulung, ausschließliche Wirtschaftsdüngervergärung in landwirtschaftlichen Biogasanlagen) gesteigert werden. Die erreichbaren Biogasausbeuten sind oben wiedergegeben (Tabellen 7 bis 10). — printed p.32', verification_note='md-verified 2026-09-05 (§5.8, printed p.32) [VC]', verified_at=now() where id='dd978bd5-273d-44b7-964c-f161ccce2226' and verification_status not in ('verified_against_standard','corrected');
-- M363-09.anlage_nicht_genehmigungspflichtig
update public.fields set verification_status='verified_against_standard', verification_quote='Relevant für mit Biogasen betriebene Feuerungsanlagen ist § 3 dieser Verordnung, wonach in diesen Anlagen nur Klärgas ${ }^{9)}$ (im Sinne der 1. BImSchV) mit einem Gehalt an Schwefelverbindungen bis zu $1 \%$ und Biogas aus der Landwirtschaft eingesetzt werden darf. — printed p.53', verification_note='md-verified 2026-09-05 (§8.1 (1. BImSchV § 3), printed p.53) [VC]', verified_at=now() where id='d77d302b-80bc-4402-b974-9321d3717904' and verification_status not in ('verified_against_standard','corrected');

