update public.fields set verification_status='verified_against_standard', verification_quote='Das hochgiftige CO entsteht durch unvollständige Verbrennung von Kohlenwasserstoffen. Die COKonzentration im Abgas von Gasmotoren wird primär von der Luftüberschusszahl $\lambda$, der Brennraumgestaltung und dem Zündzeitpunkt beeinflusst. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='36a9d55c-5bb2-46c4-a18d-5fdb141de78c' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.biogasausbeute_spez
update public.fields set verification_status='verified_against_standard', verification_quote='Aus einer bestimmten Substratmenge gewonnene Biogasmenge in l/kg CSB ${ }_{\mathrm{zu}}$ bzw. l/kg CSB ${ }_{\text {abgebaut }}$ oder $\mathrm{m}^{3} / \mathrm{Mg}$ oTM $\mathrm{zu}_{\mathrm{zu}} \mathrm{bzw} . \mathrm{m}^{3} / \mathrm{Mg}$ oTM ${ }_{\text {abgebaut }}$. | Tabelle 6: Spezifische Biogasausbeute bezogen auf die zugeführte organische Substanz in Abhängigkeit von der Vorklärzeit und dem Reinigungsziel in der biologischen Stufe (Quelle: MULNV NRW 2018) | Nur C-Elimination & & 400-460 & 415-480 & 435-500 | Eine Auswertung von über 100 Faulungsanlagen in NRW hat eine mittlere Biogasausbeute von rund $460 \mathrm{l} / \mathrm{kg}$ oTM $\mathrm{zu}_{\mathrm{zu}}$ mit einer Schwankungsbreite von 350 bis $550 \mathrm{l} / \mathrm{kg} \mathrm{oTM}_{\mathrm{zu}}$ ergeben (MKULNV NRW 2014). — printed p.21', verification_note='md-verified 2026-09-05 (§3.1; §5.2 Tab. 6, printed p.21) [VC]', verified_at=now() where id='fe54d1f1-bbeb-44d9-9e31-a7eafeccf966' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.lambda_verbrennung
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Verstromung von Biogas mittels Gasmotoren werden in der Regel Mager(mix)motoren mit einem Lambda-Wert zwischen 1,3 und 1,6 eingesetzt. Die Verbrennung erfolgt bei deutlichem Luftüberschuss. | $\lambda$ & Luftüberschusszahl — printed p.62', verification_note='md-verified 2026-09-05 (§9.4.2; §3.2 Tab. 1, printed p.62) [VC]', verified_at=now() where id='f964ddad-5f94-419b-820a-49d5b0425fde' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.scr_kat
update public.fields set verification_status='verified_against_standard', verification_quote='Durch den Einsatz von SCR-Katalysatoren (..Selective Catalytic Reduction") können bei Temperaturen unter $480^{\circ} \mathrm{C}$ Stickoxide in Abgasen reduziert werden. Dabei ist die Dosierung von Ammoniak ( $\mathrm{NH}_{3}$ ) als Reaktionspartner zwingend erforderlich, wobei Harnstoff als Ausgangsstoff hierfür genutzt wird. — printed p.63', verification_note='md-verified 2026-09-05 (§9.4.4, printed p.63) [VC]', verified_at=now() where id='9d776ae6-d0ff-4a69-be32-8f011fd6b51e' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.abgastemp_motor
update public.fields set verification_status='verified_against_standard', verification_quote='Vorteile einer Turbine sind das relativ hohe Abwärmeniveau, das bei etwa $250^{\circ} \mathrm{C}$ bis $300^{\circ} \mathrm{C}$ liegen kann, und die im Vergleich zu Gasmotoren niedrigeren Schadstoffkonzentrationen im Abgas. | So liegt die Abgastemperatur bei Gasmotoren bei $500^{\circ} \mathrm{C}$ und ermöglicht damit auch eine Dampferzeugung. — printed p.45', verification_note='md-verified 2026-09-05 (§7.3.3; §7.3.6, printed p.45) [VC]', verified_at=now() where id='8c977e19-c3bb-4e30-9686-522ee222fe30' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.formaldehyd_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Formaldehyd entsteht erst im Verbrennungsprozess durch unvollkommene Verbrennung. | In der 44. BlmSchV sind Grenzwerte festgelegt - für Neuanlagen $20 \mathrm{mg} / \mathrm{m}^{3}$, für Bestandsanlagen $30 \mathrm{mg} / \mathrm{m}^{3}$. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4 (44. BImSchV), printed p.61) [VC]', verified_at=now() where id='7b1c1b74-76d5-4a34-ac85-80db4198c082' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.nox_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Stickstoffmonoxid ( NO ) und Stickstoffdioxid ( $\mathrm{NO}_{2}$ ) sind toxische, umweltschädigende Gase. NO wird in der Atmosphäre zu NO2 aufoxidiert. Stickstoffoxide entstehen bei Verbrennungsprozessen vor allem bei hohen Temperaturen. Die Bildung von Stickstoffoxiden ist ebenso wie die CO-Bildung stark von der Luftüberschusszahl $\lambda$ abhängig (siehe Bild 7). — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='7359dae2-06ad-4448-8ce1-3e8668efac07' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.sox_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Schwefeloxide entstehen bei der Verbrennung von Schwefelwasserstoff ( $\mathrm{H}_{2} \mathrm{~S}$ ) oder gegebenenfalls schwefelhaltiger Motorölbestandteile. Schwefelwasserstoff ist ohne Maßnahmen zur Minderung/Eliminierung im Vorfeld (zum Beispiel Fällung mit Eisensalzen, Entschwefelung) in jedem Biogas vorhanden. Zur Vermeidung von unzulässigen $\mathrm{SO}_{\mathrm{x}}$-Konzentrationen im Abgas sind daher Maßnahmen vor der Verbrennung zum Teil unumgänglich. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='1bf16810-fba6-4c30-9a81-0e30b4428874' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.methanschlupf
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Reduzierung von CO-Emissionen und von unverbrannten Kohlenwasserstoff-Verbindungen (Methanschlupf) werden für verunreinigte Gase Abgasnachverbrennungssysteme angeboten. Mittels einer kleinen Stützgasfeuerung wird das Abgas wechselseitig über eine erhitzte Keramikmasse geleitet, gezündet und nachverbrannt. — printed p.63', verification_note='md-verified 2026-09-05 (§9.4.5, printed p.63) [VC]', verified_at=now() where id='c2f78444-0edb-4f39-aa6b-a24f9250c7e3' and verification_status not in ('verified_against_standard','corrected');
-- M363-10.messplatz_din_en_15259
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Überwachung der Abgasemissionen, insbesondere bei überwachungsbedürftigen, stationären Anlagen, ist ein Messplatz nach DIN EN 15259:2008-01 mit mindestens zwei um $90^{\circ}$ versetzten Messöffnungen erforderlich, ausgeführt mindestens mit jeweils $2 \frac{1}{2}$-Zoll-Stutzen. — printed p.64', verification_note='md-verified 2026-09-05 (§9.5 (DIN EN 15259:2008-01), printed p.64) [VC]', verified_at=now() where id='d0abbdf6-e131-45d7-a61e-8f7af51f9885' and verification_status not in ('verified_against_standard','corrected');
