-- M363-10.biogasausbeute_theor
update public.fields set verification_status='verified_against_standard', verification_quote='Die tatsächliche Biogasausbeute und -zusammensetzung unterscheidet sich jedoch von den in Tabelle 5 genannten theoretischen Werten, da die Substrate in der in der Praxis zur Verfügung stehenden hydraulischen Verweilzeit in der Regel nicht vollständig abgebaut werden. | Tabelle 5: Biogasausbeuten bei vollständigem Abbau der organischen Inhaltsstoffe | Kohlenhydrate & 0,79 & 50 & 14,1 & 3,9 | Proteine & 0,70 & 71 & 17,8 & 4,9 | Fette & 1,25 & 68 & 30,4 & 8,5 — printed p.20', verification_note='md-verified 2026-09-05 (§5.1 Tab. 5, printed p.20) [VC]', verified_at=now() where id='7d6a3bfd-2c66-4ef1-a8cc-0a791df5a42e' and verification_status not in ('verified_against_standard','corrected');
