-- M363-11.ex_zone
update public.fields set verification_status='verified_against_standard', verification_quote='Ferner ist die Wahrscheinlichkeit und Dauer des Auftretens gefährlicher explosionsfähiger Atmosphären zu charakterisieren. Hierzu erfolgt die Unterteilung in drei Zonen nach GefStoffV Anhang I Nummer 1.7: | I Zone 0: Bereich, in dem gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln ständig, über lange Zeiträume oder häufig vorhanden ist. | I Zone 1: Bereich, in dem sich bei Normalbetrieb gelegentlich eine gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln bilden kann. | I Zone 2: Bereich, in dem bei Normalbetrieb eine gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln normalerweise nicht oder aber nur kurzzeitig auftritt. — printed p.70', verification_note='md-verified 2026-09-05 (§10.3.2 (GefStoffV Anhang I Nr. 1.7), printed p.70) [VC]', verified_at=now() where id='0f766104-dc05-46f4-9e7d-f6192e68cb67' and verification_status not in ('verified_against_standard','corrected');
