-- M363-11.zuendtemperatur
update public.fields set verification_status='verified_against_standard', verification_quote='In einem explosionsfähigen Methan-Luftgemisch beträgt die Mindestzündtemperatur etwa $595^{\circ} \mathrm{C}$. Biogas ist damit relativ zündträge. Die Temperaturklasse T1 von technischer Ausrüstung in Ex-Zonen ist bereits ausreichend. | Zündtemperatur & ${ }^{\circ} \mathrm{C}$ & 595 & - & 270 & 650-750 — printed p.69', verification_note='md-verified 2026-09-05 (§10.3.1; §4.2 Tab. 3, printed p.69) [VC]', verified_at=now() where id='ae45a5f6-c7df-4e3f-b563-deafbef8f4ef' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.flammendurchschlagsicherung
update public.fields set verification_status='verified_against_standard', verification_quote='Ist die Entstehung einer gefährlichen, explosionsfähigen Atmosphäre im Rohrleitungssystem möglich, müssen Gasleitungen vor jeder Gasverbrauchseinrichtung bzw. vor Einrichtungen, die eine Zündquelle darstellen können, mit einer wirksamen Flammendurchschlagsicherung ausgestattet sein. — printed p.71', verification_note='md-verified 2026-09-05 (§10.3.2, printed p.71) [VC]', verified_at=now() where id='8ce204ec-3dce-4f54-9ab5-a22779a0e0d2' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.alarm_voralarm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Messung bei Gaswarngeräten richtet sich primär nach dem Personen- und Anlagenschutz. Der Gefährdung, zum Beispiel durch Explosion, wird durch Auslösen eines Voralarms (in der Regel bei $20 \%$ der UEG) bzw. Hauptalarm bei $40 \%$ der UEG begegnet. Sauerstoffmangel wird häufig bei Unterschreiten eines Anteils von $19 \%$ angezeigt. — printed p.73', verification_note='md-verified 2026-09-05 (§11.4, printed p.73) [VC]', verified_at=now() where id='00af9122-e4b8-4aa4-ae29-f4e43d0c6d0c' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.alarm_hauptalarm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Messung bei Gaswarngeräten richtet sich primär nach dem Personen- und Anlagenschutz. Der Gefährdung, zum Beispiel durch Explosion, wird durch Auslösen eines Voralarms (in der Regel bei $20 \%$ der UEG) bzw. Hauptalarm bei $40 \%$ der UEG begegnet. Sauerstoffmangel wird häufig bei Unterschreiten eines Anteils von $19 \%$ angezeigt. — printed p.73', verification_note='md-verified 2026-09-05 (§11.4, printed p.73) [VC]', verified_at=now() where id='8bf2a9ca-fb9a-4957-a355-17b621d26fc7' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.o2_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='In umschlossenen Räumen kann es durch Verdrängen der Luft durch Biogas oder Abgas zu Sauerstoffmangel kommen. Normalerweise liegt der Sauerstoffanteil der Luft bei 21 Vol.-\%. Bei Unterschreitung von 17 Vol. $-\%$ ist mit Gesundheitsgefährdungen zu rechnen. Sinkt der Sauerstoffanteil der eingeatmeten Luft unter $14 \mathrm{Vol} .-\%$ besteht Erstickungsgefahr und damit akute Lebensgefahr. — printed p.66', verification_note='md-verified 2026-09-05 (§10.2, printed p.66) [VC]', verified_at=now() where id='5235b20a-04a8-414f-8fd4-65521841343b' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.co_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='Diesbezüglich ist insbesondere Kohlenstoffmonoxid - CO relevant, das stark toxisch wirkt (siehe Tabelle 15). | Tabelle 15: Toxizität von Kohlenstoffmonoxid | Konzentration & Symptome | 35 ppm (0,0035\%) & Kopfschmerzen und Schwindel innerhalb von 6 bis 8 Stunden | 400 ppm (0,04 \%) & Starke Kopfschmerzen innerhalb von 1 bis 2 Stunden — printed p.59', verification_note='md-verified 2026-09-05 (§9.3.2 Tab. 15, printed p.59) [VC]', verified_at=now() where id='72d072db-14b8-46b1-bc4b-cff12e4cc690' and verification_status not in ('verified_against_standard','corrected');
-- M363-11.ch4_messwert
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Beurteilung einer möglichen Gefährdung durch Entzündung ausströmender bzw. angesammelter Biogase sind in explosionsgefährdeten Bereichen in regelmäßigen Zeitabständen und beim Betreten Messungen des Methan- und Sauerstoffgehalts mit Handmessgeräten durchzuführen. | Die Biogasqualität ist durch Messung des Methan- und Sauerstoffgehalts zu überwachen. Zusätzliche Informationen über den Betriebsablauf kann der Kohlenstoffdioxidgehalt liefern. — printed p.73', verification_note='md-verified 2026-09-05 (§11.3; §11.4, printed p.73) [VC]', verified_at=now() where id='3dc1b9fd-0935-49d9-bcb1-7c767a95fb61' and verification_status not in ('verified_against_standard','corrected');
