-- ===== M363-13 =====
-- M363-13.speichervolumen_anteil
update public.fields set verification_status='verified_against_standard', verification_quote='Nachfolgend werden in Tabelle 12 Empfehlungen für die Auslegung des Biogasspeichervolumens in Abhängigkeit von der Anlagenart und Energieverwertung/-erzeugung aufgeführt. Sie können als Richtwert dienen, insbesondere dann, wenn keine ausreichenden anlagenspezifischen Kenntnisse zu Ganglinien von Gasanfall und -verbrauch vorliegen. | Tabelle 12: Orientierungswerte für die Auslegung des Biogasspeichervolumens | BHKW-Grundlast & $10 \%-30 \%$ & entsprechend dem Biogasanfall von ca. 2, 5 bis 7 Stunden — printed p.37', verification_note='md-verified 2026-09-05 (§6.6 Tab. 12, printed p.37) [VC]', verified_at=now() where id='087c69d3-7a7d-4001-8258-cca7c506a998' and verification_status not in ('verified_against_standard','corrected');
-- M363-13.ueberbauung_faktor
update public.fields set verification_status='verified_against_standard', verification_quote='Dazu ist laut EEG eine 2 - bis 5 -fache Überbauung erforderlich, d. h. bei gleicher Biogasproduktion übersteigt die Leistung des BHKW diese um den Faktor 2 bis 5. (Beispiel: eine 500 kW Biogaserzeugung wird mit einem BHKW mit einer Gesamtleistung von $2,0 \mathrm{MW}$ ausgestattet → entspricht 4-facher Überbauung). — printed p.35', verification_note='md-verified 2026-09-05 (§6.4, printed p.35) [VC]', verified_at=now() where id='341540d8-d5b2-48cb-a6b8-4ceb5fcbc981' and verification_status not in ('verified_against_standard','corrected');
-- M363-13.bevorratungszeit
update public.fields set verification_status='verified_against_standard', verification_quote='Die erforderlichen Gasspeicher waren mit einer Bevorratung von 2 h bis 6 h vergleichsweise klein und dienten vor allem dem Ausgleich von Schwankungen in der Gasproduktion. | Bevorratungszeiträume von 10 h bis 15 h (bezogen auf die Gasproduktion) stellen keine Seltenheit dar. In Einzelfällen wurden schon Gasspeicher mit einer Bevorratung von 60 h errichtet, um Wochenenden komplett ohne Stromeinspeisung überbrücken zu können. — printed p.35', verification_note='md-verified 2026-09-05 (§6.4, printed p.35) [VC]', verified_at=now() where id='2b2a75c2-b7b0-4339-98e7-578501fed021' and verification_status not in ('verified_against_standard','corrected');
-- M363-13.speicher_betriebsweise
update public.fields set verification_status='verified_against_standard', verification_quote='In Tabelle 11 ist der Einfluss auf die Bemessung in Abhängigkeit der Verwertungsart und Betriebsweise dargestellt. | Tabelle 11: Einfluss der Betriebsweise von Anlagen zur Biogasnutzung auf die Bemessung von Gasspeichern | Verwertungsart & Betriebsweise & Einfluss auf die Bemessung | Stromerzeugung} & biogasgeführt & kein Einfluss/mittlere Aggregatgröße Speicherung nur als Schwankungsausgleich — printed p.35', verification_note='md-verified 2026-09-05 (§6.4 Tab. 11, printed p.35) [VC]', verified_at=now() where id='6c6965dc-62bc-4cdf-bcbb-d2d979617fec' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-14 =====
-- M363-14.verdichtertyp
update public.fields set verification_status='verified_against_standard', verification_quote='Die Druckerhöhung hängt von den eingesetzten Verbrauchern und deren Vorgaben ab. Bei der BHKWTechnik sind Seitenkanalverdichter die verbreitetste Verdichterform. Alternativ kommen Radialventilatoren zum Einsatz. Bei höheren Drücken können auch Kolbenkompressoren oder Schraubenverdichter eingesetzt werden. — printed p.40', verification_note='md-verified 2026-09-05 (§6.8, printed p.40) [VC]', verified_at=now() where id='0a3a4cc6-5693-4139-ba47-f624e9db91ba' and verification_status not in ('verified_against_standard','corrected');
-- M363-14.speichertyp
update public.fields set verification_status='verified_against_standard', verification_quote='Gebräuchlich sind große Hochdruckspeicher bis zu einem Druck von 1 MPa . | Nach Art der Funktion bzw. der Erzeugung des Drucks werden folgende Behälter unterschieden: | In der Regel werden gewichtsbelastete Biogasspeicher in einem Druckbereich von 20 hPa bis 100 hPa betrieben. Es sind auch Ausführungen bis 200 hPa bekannt. | In der Regel werden stützluftbeaufschlagte Biogasspeicher in einem Druckbereich von 5 hPa bis 50 hPa betrieben. Es sind aber auch Ausführungen bis 100 hPa bekannt. | Das Eigengewicht der Membran erzeugt einen geringen Überdruck $(<1 \mathrm{hPa})$. — printed p.38', verification_note='md-verified 2026-09-05 (§6.7, printed p.38) [VC]', verified_at=now() where id='e30cac5e-6096-4722-9007-398bf6b80a96' and verification_status not in ('verified_against_standard','corrected');
-- M363-14.speicherbetriebsdruck
update public.fields set verification_status='verified_against_standard', verification_quote='Nach Art der Funktion bzw. der Erzeugung des Drucks werden folgende Behälter unterschieden: | In der Regel werden gewichtsbelastete Biogasspeicher in einem Druckbereich von 20 hPa bis 100 hPa betrieben. Es sind auch Ausführungen bis 200 hPa bekannt. | In der Regel werden stützluftbeaufschlagte Biogasspeicher in einem Druckbereich von 5 hPa bis 50 hPa betrieben. Es sind aber auch Ausführungen bis 100 hPa bekannt. | Das Eigengewicht der Membran erzeugt einen geringen Überdruck $(<1 \mathrm{hPa})$. | Formal stellt der Geltungsbereich der Druckgeräterichtlinie (Richtlinie 2014/68/EU) eine Grenze von 500 hPa dar, die mit Biogasspeichern mit gewichtsbelasteter Membran nicht überschritten werden sollte. — printed p.39', verification_note='md-verified 2026-09-05 (§6.7, printed p.39) [VC]', verified_at=now() where id='02490b03-8a1b-4e67-bba2-3d883d6dedd2' and verification_status not in ('verified_against_standard','corrected');
-- M363-14.speicher_ummantelung
update public.fields set verification_status='verified_against_standard', verification_quote='Biogasspeicher können nach der Art ihrer Ummantelung wie folgt unterschieden werden (Bild 3): | Der Biogasspeicher mit Stahlummantelung besteht im Wesentlichen aus einem selbsttragenden Stahlmantel mit ebenem Boden und festem Dach. | Der Biogasspeicher mit Membranummantelung besteht aus einer Innenmembran, in der das Biogas gespeichert wird. Eine Außenmembran dient als Schutzhülle. | Es sind weitere Bauformen bekannt, deren Einsatzzahl bisher von untergeordneter Bedeutung ist und die deshalb im Weiteren nicht behandelt werden. — printed p.38', verification_note='md-verified 2026-09-05 (§6.7, printed p.38) [VC]', verified_at=now() where id='6e239368-5eb5-44cc-9b26-7e9fb1442e9c' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-17 =====
-- M363-17.verwertungsweg
update public.fields set verification_status='verified_against_standard', verification_quote='In Bild 4 sind Verwertungsmöglichkeiten, unterteilt in Wärmeerzeugung, Kraft-Wärme-Kopplung, Gasaufbereitung und sonstige Nutzung, aufgezeigt. | Folgende Verwertungsmöglichkeiten sind technisch ausgereift und in der Praxis bewährt: | I stationäre Gasmotoren, in der Regel als BHKW (Blockheizkraftwerk), | I Gasturbinen (konventionelle und Mikrogasturbinen) | I Kraftstoff zum Betrieb von Kraftfahrzeugen, | I Einspeisung in das Gasnetz, | I Abgabe des Biogases an Dritte zur Verwertung. — printed p.42', verification_note='md-verified 2026-09-05 (§7.1 Bild 4, printed p.42) [VC]', verified_at=now() where id='7ba1f8c7-1bfe-41eb-80af-cccb528659fc' and verification_status not in ('verified_against_standard','corrected');
-- M363-17.eta_th
update public.fields set verification_status='verified_against_standard', verification_quote='Der Wirkungsgrad der Heizkesselanlagen liegt in der Regel über $95 \%$. | Bei Nennlast können überschlägig, je nach Motorleistung ca. $33 \%$ bis zu $44 \%$ der eingesetzten Primärenergie in elektrische Energie und ca. $55 \%$ bis $48 \%$ in nutzbare thermische Energie umgesetzt werden. — printed p.43', verification_note='md-verified 2026-09-05 (§7.2; §7.3.2, printed p.43) [VC]', verified_at=now() where id='39b19b1d-e4c7-457d-883e-fd203b4abeaf' and verification_status not in ('verified_against_standard','corrected');
-- M363-17.eta_el
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Nennlast können überschlägig, je nach Motorleistung ca. $33 \%$ bis zu $44 \%$ der eingesetzten Primärenergie in elektrische Energie und ca. $55 \%$ bis $48 \%$ in nutzbare thermische Energie umgesetzt werden. | Der elektrische Wirkungsgrad von Gasturbinen liegt mit rund $25 \%$ bis $30 \%$ deutlich unter dem von Gasmotoren. | Mittels Wärmerückgewinnung durch einen integrierten Rekuperator werden elektrische Wirkungsgrade der reinen Mikrogasturbine von etwa $25 \%$ bis $31 \%$ erreicht. — printed p.44', verification_note='md-verified 2026-09-05 (§7.3.2; §7.3.3, printed p.44) [VC]', verified_at=now() where id='2af697c9-f0ab-4a7e-a090-5ff92310fc8d' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-20 =====
-- M363-20.anlagen_nr_4bimschv
update public.fields set verification_status='verified_against_standard', verification_quote='Die im Kontext der Erzeugung, Verwertung/Nutzung und Lagerung von Biogasen relevanten Anlagen sind in Tabelle 13 zusammengestellt. | Tabelle 13: Bundesimmissionschutzrechtlich genehmigungsbedürftige Anlagen im Kontext der Erzeugung, Verwertung/Nutzung und Lagerung von Biogasen | Nr. (Anhang 1, 4. BlmSchV) & Anlagenart lgekürzter, z. T. sprachlich modifizierter Auszug aus Anhang 1, 4. BlmSchV) & Leistungsgrenzen / Anlagengrößen (gem. Anhang 1, 4. BlmSchV) & Zugehörige Nummer in der TA Luft 2021 — printed p.51', verification_note='md-verified 2026-09-05 (§8.1 Tab. 13, printed p.51) [VC]', verified_at=now() where id='eb91c113-1fd0-4b26-8fb9-c1b86ad351dc' and verification_status not in ('verified_against_standard','corrected');
-- M363-20.verfahrenstyp_bimschg
update public.fields set verification_status='verified_against_standard', verification_quote='Für immissionsschutzrechtlich genehmigungsbedürftige Anlagen ist je nach Leistungsgrenze das vereinfachte Verfahren nach § 19 BlmSchG oder ein förmliches Verfahren gemäß § 10 BlmSchG durchzuführen. | Das nicht förmliche (vereinfachte) Verfahren ist für die im Anhang 1 der 4. BlmSchV aufgeführten Anlagen, die in Spalte c mit einem „V“ gekennzeichnet sind, anzuwenden. | Immissionsschutzrechtlich nicht genehmigungsbedürftig sind alle Anlagen, die nicht im Anhang 1 der 4. BImSchV aufgeführt sind oder die die Leistungsgrenzen des Anhangs 1 der 4. BImSchV unterschreiten. — printed p.50', verification_note='md-verified 2026-09-05 (§8.1 (§§ 10, 19 BImSchG), printed p.50) [VC]', verified_at=now() where id='2b63e91c-d82f-4e9d-8e94-b932a9e0ed6b' and verification_status not in ('verified_against_standard','corrected');
