-- M363-20.privilegierung_baugb
update public.fields set verification_status='verified_against_standard', verification_quote='Biogasanlagen beziehungsweise „Anlagen, die der energetischen Nutzung von Biomasse dienen“ können unter bestimmten Voraussetzungen (siehe § 35 Absatz 1 Nr. 6 BauGB) privilegiert im Außenbereich errichtet werden. Biogasanlagen sind im Außenbereich im räumlichen Zusammenhang mit einem landwirtschaftlichen Betrieb zulässig, wenn öffentliche Belange nicht entgegenstehen, die | ausreichende Erschließung gesichert ist und wenn die Kapazität einer Anlage zur Erzeugung von Biogas 2,3 Mio. Normkubikmeter Biogas pro Jahr überschreitet. — printed p.55', verification_note='md-verified 2026-09-05 (§8.2 (BauGB § 35 Abs. 1 Nr. 6), printed p.55) [VC]', verified_at=now() where id='7d1abf3d-e10a-4a99-82c8-7eaf1835325f' and verification_status not in ('verified_against_standard','corrected');
