-- ===== M363-21 =====
-- M363-21.biogasmenge_total
update public.fields set verification_status='verified_against_standard', verification_quote='Aufgrund der Brennbarkeit ist Biogas der Gefahrenkategorie „Entzündbare Gase“ (Kategorie Nr. 1.2.2 des Anhangs 1 der Störfall-Verordnung) zuzuordnen. Daraus ergibt sich, dass Biogasanlagen ab einer Menge von 10.000 kg Biogas den Grundpflichten und ab 50.000 kg den erweiterten Pflichten der Stör-fall-Verordnung unterliegen. Dabei sind die Mengen zu berücksichtigen, die in allen Anlagenteilen vorhanden sind oder vorhanden sein können. — printed p.54', verification_note='md-verified 2026-09-05 (§8.1 (12. BImSchV), printed p.54) [VC]', verified_at=now() where id='68833f5a-7821-4f43-9693-073631057678' and verification_status not in ('verified_against_standard','corrected');
-- M363-21.lagerkapazitaet_guelle
update public.fields set verification_status='verified_against_standard', verification_quote='Anlagen zum Lagern von Güllen und Gärresten die dem Abfallrecht unterliegen & Laaerkapazität von $6.500 \mathrm{~m}^{3}$ oder mehr & 5.4.8.6.13 dort Verweis auf 5.4.9.36 | Anlagen zum Lagern von Güllen und Gärresten & Laaerkapazität von $6.500 \mathrm{~m}^{3}$ oder mehr & 5.4.9.36 — printed p.53', verification_note='md-verified 2026-09-05 (§8.1 Tab. 13 Nr. 8.13/9.36, printed p.53) [VC]', verified_at=now() where id='4e0fe2da-7a6c-4b03-a955-be02f9c0770c' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-22 =====
-- M363-22.lambda_verbrennung
update public.fields set verification_status='verified_against_standard', verification_quote='Für die Verstromung von Biogas mittels Gasmotoren werden in der Regel Mager(mix)motoren mit einem Lambda-Wert zwischen 1,3 und 1,6 eingesetzt. Die Verbrennung erfolgt bei deutlichem Luftüberschuss. | $\lambda$ & Luftüberschusszahl — printed p.62', verification_note='md-verified 2026-09-05 (§9.4.2; §3.2 Tab. 1, printed p.62) [VC]', verified_at=now() where id='c78b8bfa-60ba-431e-9e3a-859bbb3b56ec' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.oxi_kat
update public.fields set verification_status='verified_against_standard', verification_quote='Durch den Einsatz von Oxidationskatalysatoren können CO und Kohlenwasserstoffe im Abgas von Gasmotoren deutlich verringert werden. Allerdings hat sich gezeigt, dass diese Katalysatoren insbesondere gegen die in Faul- und Klärgasen häufig enthaltenen Siloxane sehr empfindlich sind. — printed p.63', verification_note='md-verified 2026-09-05 (§9.4.3, printed p.63) [VC]', verified_at=now() where id='4e7edbee-c723-4530-95c8-fedbf496265b' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.scr_kat
update public.fields set verification_status='verified_against_standard', verification_quote='Durch den Einsatz von SCR-Katalysatoren (..Selective Catalytic Reduction") können bei Temperaturen unter $480^{\circ} \mathrm{C}$ Stickoxide in Abgasen reduziert werden. Dabei ist die Dosierung von Ammoniak ( $\mathrm{NH}_{3}$ ) als Reaktionspartner zwingend erforderlich, wobei Harnstoff als Ausgangsstoff hierfür genutzt wird. — printed p.63', verification_note='md-verified 2026-09-05 (§9.4.4, printed p.63) [VC]', verified_at=now() where id='1c651f41-cddb-47dd-91ed-1730ff364ba7' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.abgastemp_motor
update public.fields set verification_status='verified_against_standard', verification_quote='Vorteile einer Turbine sind das relativ hohe Abwärmeniveau, das bei etwa $250^{\circ} \mathrm{C}$ bis $300^{\circ} \mathrm{C}$ liegen kann, und die im Vergleich zu Gasmotoren niedrigeren Schadstoffkonzentrationen im Abgas. | So liegt die Abgastemperatur bei Gasmotoren bei $500^{\circ} \mathrm{C}$ und ermöglicht damit auch eine Dampferzeugung. — printed p.45', verification_note='md-verified 2026-09-05 (§7.3.3; §7.3.6, printed p.45) [VC]', verified_at=now() where id='dd39d100-8d16-4119-b744-e16328974b8f' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.formaldehyd_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Formaldehyd entsteht erst im Verbrennungsprozess durch unvollkommene Verbrennung. | In der 44. BlmSchV sind Grenzwerte festgelegt - für Neuanlagen $20 \mathrm{mg} / \mathrm{m}^{3}$, für Bestandsanlagen $30 \mathrm{mg} / \mathrm{m}^{3}$. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4 (44. BImSchV), printed p.61) [VC]', verified_at=now() where id='8eef266f-da85-449b-975a-a86b671a5613' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.nox_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Stickstoffmonoxid ( NO ) und Stickstoffdioxid ( $\mathrm{NO}_{2}$ ) sind toxische, umweltschädigende Gase. NO wird in der Atmosphäre zu NO2 aufoxidiert. Stickstoffoxide entstehen bei Verbrennungsprozessen vor allem bei hohen Temperaturen. Die Bildung von Stickstoffoxiden ist ebenso wie die CO-Bildung stark von der Luftüberschusszahl $\lambda$ abhängig (siehe Bild 7). — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='1d5c9a83-deb2-4253-924d-1cc4ddef5557' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.co_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Das hochgiftige CO entsteht durch unvollständige Verbrennung von Kohlenwasserstoffen. Die COKonzentration im Abgas von Gasmotoren wird primär von der Luftüberschusszahl $\lambda$, der Brennraumgestaltung und dem Zündzeitpunkt beeinflusst. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='38d4a59d-09f4-40af-86e0-1247197d5b70' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.sox_abgas
update public.fields set verification_status='verified_against_standard', verification_quote='Schwefeloxide entstehen bei der Verbrennung von Schwefelwasserstoff ( $\mathrm{H}_{2} \mathrm{~S}$ ) oder gegebenenfalls schwefelhaltiger Motorölbestandteile. Schwefelwasserstoff ist ohne Maßnahmen zur Minderung/Eliminierung im Vorfeld (zum Beispiel Fällung mit Eisensalzen, Entschwefelung) in jedem Biogas vorhanden. Zur Vermeidung von unzulässigen $\mathrm{SO}_{\mathrm{x}}$-Konzentrationen im Abgas sind daher Maßnahmen vor der Verbrennung zum Teil unumgänglich. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4, printed p.61) [VC]', verified_at=now() where id='c6289053-788c-40d0-b51d-7da942a1b17f' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.methanschlupf
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Reduzierung von CO-Emissionen und von unverbrannten Kohlenwasserstoff-Verbindungen (Methanschlupf) werden für verunreinigte Gase Abgasnachverbrennungssysteme angeboten. Mittels einer kleinen Stützgasfeuerung wird das Abgas wechselseitig über eine erhitzte Keramikmasse geleitet, gezündet und nachverbrannt. — printed p.63', verification_note='md-verified 2026-09-05 (§9.4.5, printed p.63) [VC]', verified_at=now() where id='28169dbc-8d15-4880-84c2-e57ccb201fc2' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.messplatz_din_en_15259
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Überwachung der Abgasemissionen, insbesondere bei überwachungsbedürftigen, stationären Anlagen, ist ein Messplatz nach DIN EN 15259:2008-01 mit mindestens zwei um $90^{\circ}$ versetzten Messöffnungen erforderlich, ausgeführt mindestens mit jeweils $2 \frac{1}{2}$-Zoll-Stutzen. — printed p.64', verification_note='md-verified 2026-09-05 (§9.5 (DIN EN 15259:2008-01), printed p.64) [VC]', verified_at=now() where id='65b0f193-0e78-430b-8f73-26824b497eee' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.h2s_grenzwert_motor
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 14: Zuordnung von Methankonzentration im Faulgas zu den beispielhaften Grenzwerten von $150 \mathrm{ppm} / 10 \mathrm{kWh}$ bzw. $8 \mathrm{ppm} / 10 \mathrm{kWh}$ (Quelle: Merkblatt DWA-M 212:2020) | Methankonzentration & Zulässiger Schwefelwasserstoffanteil bei einem Grenzwert von $150 \mathrm{ppm} / 10 \mathrm{kWh}$ (Werte gerundet) & Zulässiger Schwefelwasserstoffanteil bei einem Grenzwert von $8 \mathrm{ppm} / 10 \mathrm{kWh}$ (Werte gerundet) | $65 \% \mathrm{CH}_{4}$ & 231 ppm & 12 ppm — printed p.57', verification_note='md-verified 2026-09-05 (§9.1 Tab. 14, printed p.57) [VC]', verified_at=now() where id='87a3b6ca-07ef-46eb-8972-10af4edd3dc9' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.anlagenstatus
update public.fields set verification_status='verified_against_standard', verification_quote='Formaldehyd entsteht erst im Verbrennungsprozess durch unvollkommene Verbrennung. | In der 44. BlmSchV sind Grenzwerte festgelegt - für Neuanlagen $20 \mathrm{mg} / \mathrm{m}^{3}$, für Bestandsanlagen $30 \mathrm{mg} / \mathrm{m}^{3}$. — printed p.61', verification_note='md-verified 2026-09-05 (§9.3.4 (44. BImSchV), printed p.61) [VC]', verified_at=now() where id='c613e466-e60b-4791-9fd7-9f69e7715421' and verification_status not in ('verified_against_standard','corrected');
-- M363-22.h2s_ppm
update public.fields set verification_status='verified_against_standard', verification_quote='Bei Schwefelwasserstoff wird häufig ein Kennwert in ppm verwendet, aber auch $\mathrm{mg} / \mathrm{m}^{3}$ Biogas. Je nach Kennwert und Bezugnahme ist somit eine Umrechnung erforderlich. | Dabei gilt | $100 \mathrm{ppm} \mathrm{H}_{2} \mathrm{Sim}$ Biogas $\approx 140 \mathrm{mg} / \mathrm{m}^{3}$ bei $20^{\circ} \mathrm{C}$ — printed p.56', verification_note='md-verified 2026-09-05 (§9.1, printed p.56) [VC]', verified_at=now() where id='0576ac5f-8cd0-49db-a00e-e7c226fe9930' and verification_status not in ('verified_against_standard','corrected');

-- ===== M363-23 =====
-- M363-23.ex_zone
update public.fields set verification_status='verified_against_standard', verification_quote='Ferner ist die Wahrscheinlichkeit und Dauer des Auftretens gefährlicher explosionsfähiger Atmosphären zu charakterisieren. Hierzu erfolgt die Unterteilung in drei Zonen nach GefStoffV Anhang I Nummer 1.7: | I Zone 0: Bereich, in dem gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln ständig, über lange Zeiträume oder häufig vorhanden ist. | I Zone 1: Bereich, in dem sich bei Normalbetrieb gelegentlich eine gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln bilden kann. | I Zone 2: Bereich, in dem bei Normalbetrieb eine gefährliche explosionsfähige Atmosphäre als Gemisch aus Luft und brennbaren Gasen, Dämpfen oder Nebeln normalerweise nicht oder aber nur kurzzeitig auftritt. — printed p.70', verification_note='md-verified 2026-09-05 (§10.3.2 (GefStoffV Anhang I Nr. 1.7), printed p.70) [VC]', verified_at=now() where id='54cd28eb-67eb-4e75-aa2c-b794bb334de9' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.ueg_methan
update public.fields set verification_status='verified_against_standard', verification_quote='Der Explosionsbereich von Methan allein liegt bei Luftzumischung zwischen 4,4 Vol.-\% Methan (untere Explosionsgrenze) und $16,5 \mathrm{~V}$ ol. $-\%$ Methan (obere Explosionsgrenze) (siehe Bild 8). | UEG & Untere Explosionsgrenze | l über $16,5 \mathrm{Vol} .-\%$ Methan in Luft, | I unter 4,4 Vol.-\% Methan in Luft, — printed p.68', verification_note='md-verified 2026-09-05 (§10.3.1; §3.2 Tab. 1, printed p.68) [VC]', verified_at=now() where id='1c2ce3d5-4617-4009-9740-091f46ccecc4' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.oeg_methan
update public.fields set verification_status='verified_against_standard', verification_quote='Der Explosionsbereich von Methan allein liegt bei Luftzumischung zwischen 4,4 Vol.-\% Methan (untere Explosionsgrenze) und $16,5 \mathrm{~V}$ ol. $-\%$ Methan (obere Explosionsgrenze) (siehe Bild 8). | OEG & Obere Explosionsgrenze | l über $16,5 \mathrm{Vol} .-\%$ Methan in Luft, | I unter 4,4 Vol.-\% Methan in Luft, — printed p.68', verification_note='md-verified 2026-09-05 (§10.3.1; §3.2 Tab. 1, printed p.68) [VC]', verified_at=now() where id='c82d3158-3445-4f99-8309-2eed74f2b00e' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.zuendtemperatur
update public.fields set verification_status='verified_against_standard', verification_quote='In einem explosionsfähigen Methan-Luftgemisch beträgt die Mindestzündtemperatur etwa $595^{\circ} \mathrm{C}$. Biogas ist damit relativ zündträge. Die Temperaturklasse T1 von technischer Ausrüstung in Ex-Zonen ist bereits ausreichend. | Zündtemperatur & ${ }^{\circ} \mathrm{C}$ & 595 & - & 270 & 650-750 — printed p.69', verification_note='md-verified 2026-09-05 (§10.3.1; §4.2 Tab. 3, printed p.69) [VC]', verified_at=now() where id='20865148-a6dc-43e1-b4f5-780952fcc112' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.flammendurchschlagsicherung
update public.fields set verification_status='verified_against_standard', verification_quote='Ist die Entstehung einer gefährlichen, explosionsfähigen Atmosphäre im Rohrleitungssystem möglich, müssen Gasleitungen vor jeder Gasverbrauchseinrichtung bzw. vor Einrichtungen, die eine Zündquelle darstellen können, mit einer wirksamen Flammendurchschlagsicherung ausgestattet sein. — printed p.71', verification_note='md-verified 2026-09-05 (§10.3.2, printed p.71) [VC]', verified_at=now() where id='f8cf4938-5526-4f10-95c3-286ef2133fda' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.alarm_voralarm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Messung bei Gaswarngeräten richtet sich primär nach dem Personen- und Anlagenschutz. Der Gefährdung, zum Beispiel durch Explosion, wird durch Auslösen eines Voralarms (in der Regel bei $20 \%$ der UEG) bzw. Hauptalarm bei $40 \%$ der UEG begegnet. Sauerstoffmangel wird häufig bei Unterschreiten eines Anteils von $19 \%$ angezeigt. — printed p.73', verification_note='md-verified 2026-09-05 (§11.4, printed p.73) [VC]', verified_at=now() where id='ae9b555f-5a43-43a1-ab9c-3eaf95d4a23b' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.alarm_hauptalarm
update public.fields set verification_status='verified_against_standard', verification_quote='Die Messung bei Gaswarngeräten richtet sich primär nach dem Personen- und Anlagenschutz. Der Gefährdung, zum Beispiel durch Explosion, wird durch Auslösen eines Voralarms (in der Regel bei $20 \%$ der UEG) bzw. Hauptalarm bei $40 \%$ der UEG begegnet. Sauerstoffmangel wird häufig bei Unterschreiten eines Anteils von $19 \%$ angezeigt. — printed p.73', verification_note='md-verified 2026-09-05 (§11.4, printed p.73) [VC]', verified_at=now() where id='98eb8464-7b7d-4a36-80c9-8738654d1add' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.o2_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='In umschlossenen Räumen kann es durch Verdrängen der Luft durch Biogas oder Abgas zu Sauerstoffmangel kommen. Normalerweise liegt der Sauerstoffanteil der Luft bei 21 Vol.-\%. Bei Unterschreitung von 17 Vol. $-\%$ ist mit Gesundheitsgefährdungen zu rechnen. Sinkt der Sauerstoffanteil der eingeatmeten Luft unter $14 \mathrm{Vol} .-\%$ besteht Erstickungsgefahr und damit akute Lebensgefahr. — printed p.66', verification_note='md-verified 2026-09-05 (§10.2, printed p.66) [VC]', verified_at=now() where id='1b8d7959-f82d-408f-941e-f9e08ed7d5be' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.co_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='Diesbezüglich ist insbesondere Kohlenstoffmonoxid - CO relevant, das stark toxisch wirkt (siehe Tabelle 15). | Tabelle 15: Toxizität von Kohlenstoffmonoxid | Konzentration & Symptome | 35 ppm (0,0035\%) & Kopfschmerzen und Schwindel innerhalb von 6 bis 8 Stunden | 400 ppm (0,04 \%) & Starke Kopfschmerzen innerhalb von 1 bis 2 Stunden — printed p.59', verification_note='md-verified 2026-09-05 (§9.3.2 Tab. 15, printed p.59) [VC]', verified_at=now() where id='94c7b9a4-517d-44d9-9904-9128b91060c4' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.ch4_messwert
update public.fields set verification_status='verified_against_standard', verification_quote='Zur Beurteilung einer möglichen Gefährdung durch Entzündung ausströmender bzw. angesammelter Biogase sind in explosionsgefährdeten Bereichen in regelmäßigen Zeitabständen und beim Betreten Messungen des Methan- und Sauerstoffgehalts mit Handmessgeräten durchzuführen. | Die Biogasqualität ist durch Messung des Methan- und Sauerstoffgehalts zu überwachen. Zusätzliche Informationen über den Betriebsablauf kann der Kohlenstoffdioxidgehalt liefern. — printed p.73', verification_note='md-verified 2026-09-05 (§11.3; §11.4, printed p.73) [VC]', verified_at=now() where id='ee6051ac-da48-41eb-b450-6dfdc8ecb0ad' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.co2_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 16: Wirkungen von Kohlenstoffdioxid (Quelle: GESTIS-Stoffdatenbank) | Kohlenstoffdioxidanteil in der Atemluft | Wirkung | $0,5 \%\left(9.100 \mathrm{mg} / \mathrm{m}^{3}\right)$ & Arbeitsplatzgrenzwert (AGW) nach TRGS 900:2021 | ab 10 \% & 10 min bis 20 min Bewusstseinsverlust mit kurzfristig folgendem Tod — printed p.66', verification_note='md-verified 2026-09-05 (§10.2 Tab. 16, printed p.66) [VC]', verified_at=now() where id='e54029ca-3890-42d7-adc2-21562cc0a7d4' and verification_status not in ('verified_against_standard','corrected');
-- M363-23.h2s_atemluft
update public.fields set verification_status='verified_against_standard', verification_quote='Tabelle 17: Wirkungen von Schwefelwasserstoff (Quelle: GESTIS-Stoffdatenbank) | Schwefelwasserstoffanteil in der Atemluft | 5 ppm & Arbeitsplatzgrenzwert gemäß TRGS 900:2006 | ab ca. 500 ppm & letal (tödlich) nach Inhalation über ca. 30 min | ab ca. 1.000 ppm & unmittelbar Kollaps/Atemlähmung — printed p.67', verification_note='md-verified 2026-09-05 (§10.2 Tab. 17, printed p.67) [VC]', verified_at=now() where id='8ea71056-681a-49d7-9b11-4dacb8721261' and verification_status not in ('verified_against_standard','corrected');

-- ===== equations =====
-- M363-05 Gl(1) -> c_ab
update public.equations set verification_status='verified_against_standard', verification_quote='Auch besteht ein empirischer Zusammenhang zum $\mathrm{AT}_{4}$ (Atmungsaktivität in 4 Tagen, siehe DepV, Anhang 4), der bei Werten $\mathrm{AT}_{4}>10$ mit nachstehender Gleichung ausgedrückt werden kann (siehe VDI 3790 Blatt 2): | C_{a b}=3,75 \cdot \mathrm{AT}_{4}-C | $C$ & $\mathrm{~kg} / \mathrm{Mg}$ TM & Konstante mit dem empirischen Wert $7,5 \mathrm{~kg} / \mathrm{Mg}$ TM — printed p.30', verification_note='md-verified 2026-09-05 (§5.7 Gl. (1), printed p.30) [VC]', verified_at=now() where id='b0b59b76-b242-4fe0-aea0-bc6a6a841012' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(2) -> c_ab
update public.equations set verification_status='verified_against_standard', verification_quote='Bei Werten $\mathrm{AT}_{4}<10$ kann folgender empirischer Zusammenhang angegeben werden: | C_{a b}=3 \cdot A T_{4} — printed p.30', verification_note='md-verified 2026-09-05 (§5.7 Gl. (2), printed p.30) [VC]', verified_at=now() where id='b969f2eb-4648-49ea-83c2-2e6a32507878' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(3) -> g_e
update public.equations set verification_status='verified_against_standard', verification_quote='Die Gasausbeute in $\mathrm{m}^{3} / \mathrm{Mg}$ FM ergibt sich durch: | G_{\mathrm{e}}=C_{\mathrm{ab}} \cdot 1,868 \cdot(100-\mathrm{WG}) / 100 — printed p.30', verification_note='md-verified 2026-09-05 (§5.7 Gl. (3), printed p.30) [VC]', verified_at=now() where id='b6cc4ba5-552d-4a9e-baa0-328537026c35' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(4a) -> g_t
update public.equations set verification_status='verified_against_standard', verification_quote='Der Deponiegasbildungsprozess lässt sich gut mit einem Zerfallsprozess entsprechend einem Abbau erster Ordnung modellieren. Dieser Prozess folgt einer Exponentialfunktion mit negativem Exponenten, der sich wie folgt ausdrücken lässt: | G_{t}=G_{e} \cdot\left(1-\mathrm{e}^{-k t}\right) \operatorname{oder} G_{t d}=G_{e} \cdot k \cdot \mathrm{e}^{-k t} — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 Gl. (4), printed p.31) [VC]', verified_at=now() where id='cfab7241-ba1b-40d9-8947-bf957e4542be' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(4b) -> g_td
update public.equations set verification_status='verified_against_standard', verification_quote='G_{t}=G_{e} \cdot\left(1-\mathrm{e}^{-k t}\right) \operatorname{oder} G_{t d}=G_{e} \cdot k \cdot \mathrm{e}^{-k t} | $G_{\mathrm{td}}$ & $\mathrm{m}^{3} / \mathrm{Mg}$ & im Jahr $t$ insgesamt pro Mg FM durchschnittlich gebildetes spezifisches Gasvolumen — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 Gl. (4), printed p.31) [VC]', verified_at=now() where id='78e61753-6fa8-42bc-97b2-6aa2f4607a83' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(5-f3) -> f_3
update public.equations set verification_status='verified_against_standard', verification_quote='$f_{3}$ & & Faktor zur Berücksichtigung der Assimilation mit $f_{3}=(0,014 \cdot T+0,28)$ mit $T$ als der durchschnittlichen Temperatur in ${ }^{\circ} \mathrm{C}$ im Deponiekörper (für Deponiebedingungen ca. $20^{\circ} \mathrm{C}$ bis $40^{\circ} \mathrm{C}$ ) — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 Gl. (5), printed p.31) [VC]', verified_at=now() where id='165ae837-b05d-44d6-8872-714929bc0ddb' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(5) -> g_td
update public.equations set verification_status='verified_against_standard', verification_quote='Von den Autoren wurde ein Modell vorgeschlagen, welches aus Versuchen bei der Schlammfaulung abgeleitet wurde (Rettenberger 1993). | G_{t d}=1,868 \cdot C_{a b} \cdot f_{1} \cdot f_{2} \cdot f_{3} \cdot M_{n} \cdot k \cdot e^{-k t} — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 Gl. (5) (Tabasaran-Rettenberger), printed p.31) [VC]', verified_at=now() where id='905fe4b9-4926-4346-b9a0-92d9adde7df2' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(6) -> ch4_erz_t
update public.equations set verification_status='verified_against_standard', verification_quote='Hierbei handelt es sich ebenfalls um ein Modell auf der Basis eines Abbaus erster Ordnung, für das in der Literatur eine Reihe von Parametern zur Verfügung gestellt werden. | \mathrm{CH}_{4, \mathrm{erz}, \mathrm{~T}}=\mathrm{DDOC}_{\mathrm{m}, \text { decomp, } \mathrm{T}} \cdot F \cdot 16 / 12 — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 Gl. (6) (IPCC Waste Model), printed p.31) [VC]', verified_at=now() where id='6e9fca7d-186d-4746-879b-c58579189926' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(7) -> ddoc_m_decomp_t
update public.equations set verification_status='verified_against_standard', verification_quote='Die Berechnung des Abbaus erfolgt dann nach folgendem Ansatz: | \mathrm{DDOC}_{\mathrm{m}, \text { decomp }, \mathrm{T}}=\mathrm{DDOC}_{\mathrm{ma}, \mathrm{~T}-1}-\left(1-\mathrm{e}^{-\mathrm{k}}\right) — printed p.32', verification_note='md-verified 2026-09-05 (§5.7 Gl. (7) (IPCC Waste Model), printed p.32) [VC]', verified_at=now() where id='ea86e593-47c6-48e7-8354-cb85ba511843' and verification_status <> 'verified_against_standard';
-- M363-05 Gl(k-half) -> k_abbau
update public.equations set verification_status='verified_against_standard', verification_quote='$k$ & 1/a & Abbaukonstante mit $k=-\ln (0,5) / t_{1 / 2}$ wobei $t_{1 / 2}$ = Halbwertszeit der Gasbildungsfunktion, etwa in der Größenordnung 4 a bis 6 a — printed p.31', verification_note='md-verified 2026-09-05 (§5.7 (Definition zu Gl. 4), printed p.31) [VC]', verified_at=now() where id='13f32698-4844-449f-b0fc-6f142d32313c' and verification_status <> 'verified_against_standard';
-- M363-10 Gl(h2s-mg) -> h2s_mg_per_m3
update public.equations set verification_status='verified_against_standard', verification_quote='Bei Schwefelwasserstoff wird häufig ein Kennwert in ppm verwendet, aber auch $\mathrm{mg} / \mathrm{m}^{3}$ Biogas. Je nach Kennwert und Bezugnahme ist somit eine Umrechnung erforderlich. | Dabei gilt | $100 \mathrm{ppm} \mathrm{H}_{2} \mathrm{Sim}$ Biogas $\approx 140 \mathrm{mg} / \mathrm{m}^{3}$ bei $20^{\circ} \mathrm{C}$ — printed p.56', verification_note='md-verified 2026-09-05 (§9.1, printed p.56) [VC]', verified_at=now() where id='2df30411-3305-4d78-857d-de9d57e4b838' and verification_status <> 'verified_against_standard';
